class Produto {
  nome: string;
  constructor(nome: string) {
    this.nome = nome;
  }
  exibir(): string {
    return this.nome;
  }
}

const lista = [new Produto("Mouse"), new Produto("Teclado")];
for (const p of lista) {
  console.log(p.exibir());
}
